import React, { useState, useEffect, useRef } from 'react';
import { 
  Search as SearchIcon, 
  FileSpreadsheet, 
  Trash2,
  Calendar,
  AlertTriangle,
  Copy,
  ChevronDown,
  RotateCcw
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { db } from './firebase';
import { collection, onSnapshot, query, writeBatch, doc, getDocs } from 'firebase/firestore';

// KONFIGURASI TELEGRAM BOT
const TELEGRAM_BOT_TOKEN = "8571888481:AAGdqdiaa4kPd_YWqfZauELZ1-ACiMV0iYg";
const TELEGRAM_CHAT_ID = "-1003574594574";

// HELPER: Anti-Duplikat Telegram via LocalStorage
const getSentTelegramKeys = () => {
  try {
    const saved = localStorage.getItem('telegram_sent_trxs');
    return saved ? JSON.parse(saved) : [];
  } catch (err) {
    return [];
  }
};

const markTelegramKeyAsSent = (trxKey) => {
  try {
    const sent = getSentTelegramKeys();
    if (!sent.includes(trxKey)) {
      sent.push(trxKey);
      if (sent.length > 3000) sent.shift(); // Batasi cache maksimal 3000 data
      localStorage.setItem('telegram_sent_trxs', JSON.stringify(sent));
    }
  } catch (err) {
    console.error("Gagal simpan cache Telegram:", err);
  }
};

const LogSpeedPanel = ({ excelData = null }) => {
  const [data, setData] = useState([]);
  const [fileName, setFileName] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [dateFilter, setDateFilter] = useState('');
  const [isAutoFit, setIsAutoFit] = useState(false);
  const fileInputRef = useRef(null);
  const lastProcessedDataRef = useRef(null);

  // State Tambahan Edit Tanggal Upload
  const [useCustomUploadDate, setUseCustomUploadDate] = useState(false);
  const [customUploadDate, setCustomUploadDate] = useState('');

  // State Filter Khusus Cek SN N/A
  const [filterNaOnly, setFilterNaOnly] = useState(false);

  const defaultWidths = {
    tglEntri: 100, 
    tglStatus: 100, 
    produk: 50,
    tujuan: 100, 
    sn: 150, 
    status: 60,
    hargaJual: 80,
    hargaBeli: 80,
    laba: 70,
    supplier: 90,
    jawabanProvider: 200
  };

  const [columnWidths, setColumnWidths] = useState(defaultWidths);

  const resizingColumn = useRef(null);
  const startX = useRef(0);
  const startWidth = useRef(0);

  // Helper Format Rupiah
  const formatRupiah = (val) => {
    const num = Number(val);
    if (isNaN(num)) return val ? String(val) : "0";
    return num.toLocaleString('id-ID');
  };

  // Evaluasi Status Laba (Negatif / NA / Kosong / Non-numeric)
  const evaluateLaba = (labaVal) => {
    if (labaVal === null || labaVal === undefined) {
      return { isProblem: true, reason: "Laba Kosong / NA" };
    }
    const strVal = String(labaVal).trim().toUpperCase();
    if (strVal === "" || strVal === "NA" || strVal === "N/A" || strVal === "NULL" || strVal === "UNDEFINED") {
      return { isProblem: true, reason: "Laba N/A atau Kosong" };
    }
    const numVal = Number(String(labaVal).replace(/,/g, '').trim());
    if (isNaN(numVal)) {
      return { isProblem: true, reason: `Format Laba Tidak Valid (${strVal})` };
    }
    if (numVal < 0) {
      return { isProblem: true, reason: `Laba Negatif (${formatRupiah(numVal)})` };
    }
    return { isProblem: false, reason: "" };
  };

  // Evaluasi Status Transaksi Wajib Mengacu pada Kolom S (JANGAN MEMBACA DARI KOLOM O / SN)
  const parseStatusFromRow = (item) => {
    // 1. Ambil status utama dari Kolom S (Excel index S atau key 'Status')
    let rawStatus = item['S'] || item['s'] || item.status || item.Status || item.STATUS || item.status_provider || item.statusProvider || item['Keterangan Status'] || "";

    if (!rawStatus) {
      const foundKey = Object.keys(item).find(k => k.toLowerCase() === 'status' || k.toLowerCase() === 'sts');
      if (foundKey) rawStatus = item[foundKey];
    }

    const kolomS = String(rawStatus).trim().toUpperCase();
    const jawabanProvider = String(item['N'] || item.jawabanProvider || item['Jawaban Provider'] || item.message || item.Message || "").trim().toUpperCase();

    // Keyword Kegagalan Komprehensif
    const failKeywords = [
      "GAGAL", "REJECT", "CANCEL", "FAIL", "BATAL", "ERROR", 
      "SISA SALDO TIDAK CUKUP", "SALDO TIDAK CUKUP", "PIN SALAH", 
      "EXPIRED", "REFUND", "RJT", "DITOLAK", "TIBA-TIBA GAGAL", "INVALID"
    ];

    const isFailInKolomS = failKeywords.some(kw => kolomS.includes(kw));
    const isFailInJawaban = failKeywords.some(kw => jawabanProvider.includes(kw));

    // Jika Kolom S atau Jawaban Provider mengindikasikan gagal, kembalikan Gagal
    if (isFailInKolomS || isFailInJawaban) {
      return "Gagal";
    }

    const successKeywords = ["SUKSES", "SUCCESS", "OK", "BERHASIL"];
    const isSuccessInKolomS = successKeywords.some(kw => kolomS.includes(kw));
    const isSuccessInJawaban = successKeywords.some(kw => jawabanProvider.includes(kw));

    if (isSuccessInKolomS || isSuccessInJawaban) {
      return "Sukses";
    }

    if (kolomS) {
      const str = String(kolomS).trim();
      return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
    }

    return "Sukses";
  };

  // Parsing Supplier Otomatis (Kolom H / Nama Supplier / Jawaban Provider)
  const parseSupplierFromRow = (item) => {
    let raw = item.supplier || item.Supplier || item.SUPPLIER || item.vendor || item.Vendor || item['Nama Supplier'] || item['Provider'] || "";
    if (!raw && item['H']) raw = item['H'];

    let str = String(raw).trim();
    if (str && str.toUpperCase() !== "UNKNOWN" && str.toUpperCase() !== "") {
      return str.toUpperCase();
    }

    // Pendeteksian Tambahan dari Jawaban Provider atau Kolom Lain
    const combinedText = `${item['N'] || ''} ${item['D'] || ''} ${item['F'] || ''} ${item['S'] || ''} ${item.jawabanProvider || ''}`.toUpperCase();
    
    if (combinedText.includes("DIGIFLAZZ")) return "DIGIFLAZZ";
    if (combinedText.includes("DAS")) return "DAS";
    if (combinedText.includes("AMC")) return "AMC";
    if (combinedText.includes("HAO")) return "HAO";
    if (combinedText.includes("NEWBIEZ")) return "NEWBIEZ";
    if (combinedText.includes("OASIS")) return "OASIS";
    if (combinedText.includes("ANTUM")) return "ANTUM";

    return str ? str.toUpperCase() : "UNKNOWN";
  };

  // Load & Sync Data Realtime dari Firebase Firestore (Transaksi Terbaru Paling Atas)
  useEffect(() => {
    let unsubscribe = () => {};
    try {
      const q = query(collection(db, "speed_log_data"));
      unsubscribe = onSnapshot(q, (snapshot) => {
        const fetchedData = snapshot.docs.map(docSnap => {
          const d = docSnap.data();
          return {
            id: docSnap.id,
            ...d,
            rawDate: d.rawDate ? new Date(d.rawDate) : new Date()
          };
        });
        
        // Transaksi Terbaru Wajib Paling Atas (Descending)
        fetchedData.sort((a, b) => b.rawDate - a.rawDate);
        setData(fetchedData);
        localStorage.setItem('speed_log_data', JSON.stringify(fetchedData));
      }, (error) => {
        console.error("Firebase sync fallback to LocalStorage:", error);
        loadFromLocalStorage();
      });
    } catch (err) {
      console.error("Firestore Error, reading local storage:", err);
      loadFromLocalStorage();
    }

    return () => unsubscribe();
  }, []);

  const loadFromLocalStorage = () => {
    const savedData = localStorage.getItem('speed_log_data');
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        const formatted = parsed.map(item => ({
          ...item,
          rawDate: new Date(item.rawDate)
        }));
        // Transaksi Terbaru Paling Atas (Descending)
        formatted.sort((a, b) => b.rawDate - a.rawDate);
        setData(formatted);
      } catch (err) {
        console.error("Gagal membaca cache log speed:", err);
      }
    }
  };

  // Sync Otomatis Saat Props excelData Berubah dari App.js
  useEffect(() => {
    if (excelData && Array.isArray(excelData) && excelData.length > 0) {
      if (lastProcessedDataRef.current !== excelData) {
        lastProcessedDataRef.current = excelData;
        processAndSetData(excelData);
      }
    }
  }, [excelData]);

  // Auto-fit Logic
  useEffect(() => {
    if (isAutoFit) {
      setColumnWidths({
        tglEntri: 120, tglStatus: 120, produk: 80, tujuan: 140, sn: 180, status: 80,
        hargaJual: 100, hargaBeli: 100, laba: 90, supplier: 110, jawabanProvider: 300
      });
    } else {
      setColumnWidths(defaultWidths);
    }
  }, [isAutoFit]);

  useEffect(() => {
    const onMouseMove = (e) => {
      if (!resizingColumn.current) return;
      const clientX = e.touches ? e.touches[0].pageX : e.pageX;
      const diff = clientX - startX.current;
      const newWidth = Math.max(5, startWidth.current + diff);
      setColumnWidths(prev => ({
        ...prev,
        [resizingColumn.current]: newWidth
      }));
    };
    
    const onMouseUp = () => { 
      resizingColumn.current = null; 
      document.body.style.cursor = 'default'; 
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('touchmove', onMouseMove);
    window.addEventListener('touchend', onMouseUp);
    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('touchmove', onMouseMove);
      window.removeEventListener('touchend', onMouseUp);
    };
  }, []);

  const handleResizeStart = (e, colKey) => {
    const clientX = e.touches ? e.touches[0].pageX : e.pageX;
    resizingColumn.current = colKey;
    startX.current = clientX;
    startWidth.current = columnWidths[colKey];
    document.body.style.cursor = 'col-resize';
  };

  const handleReset = () => {
    setSearchTerm('');
    setStatusFilter('ALL');
    setDateFilter('');
    setIsAutoFit(false);
    setUseCustomUploadDate(false);
    setCustomUploadDate('');
    setFilterNaOnly(false);
    setColumnWidths(defaultWidths);
  };

  // Reset Total Firestore & LocalStorage (Hanya jika reset Keseluruhan)
  const handleResetDatabase = async () => {
    if (!window.confirm("Apakah Om yakin ingin MENGHAPUS PERMANEN seluruh database Log Speed dari Firebase? Data tidak bisa dikembalikan!")) {
      return;
    }

    try {
      const querySnapshot = await getDocs(collection(db, "speed_log_data"));
      const docs = querySnapshot.docs;
      
      const BATCH_SIZE = 400;
      for (let i = 0; i < docs.length; i += BATCH_SIZE) {
        const chunk = docs.slice(i, i + BATCH_SIZE);
        const batch = writeBatch(db);
        chunk.forEach(d => {
          batch.delete(d.ref);
        });
        await batch.commit();
      }

      setData([]);
      localStorage.removeItem('speed_log_data');
      if (fileInputRef.current) fileInputRef.current.value = "";
      setFileName('');
      alert("Database Firebase & Cache berhasil di-reset total!");
    } catch (err) {
      console.error("Gagal melakukan reset database Firebase:", err);
      alert("Gagal reset database: " + err.message);
    }
  };

  const clearFile = () => {
    setFileName('');
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const formatOtomaxDate = (dateObj, manualTime = null) => {
    if (!(dateObj instanceof Date) || isNaN(dateObj)) return "-";
    const pad = (num) => num.toString().padStart(2, '0');
    const d = pad(dateObj.getDate());
    const m = pad(dateObj.getMonth() + 1);
    const y = dateObj.getFullYear().toString().slice(-2);
    
    let timeStr = "";
    if (manualTime) {
      timeStr = manualTime.replace(/:/g, '.');
    } else {
      const h = pad(dateObj.getHours());
      const min = pad(dateObj.getMinutes());
      const s = pad(dateObj.getSeconds());
      timeStr = `${h}.${min}.${s}`;
    }
    
    return `${d}/${m}/${y} ${timeStr}`;
  };

  // Kirim Telegram Notifikasi Komplain SN N/A
  const sendTelegramAlert = async (naItems) => {
    if (!TELEGRAM_BOT_TOKEN || !TELEGRAM_CHAT_ID || TELEGRAM_BOT_TOKEN === "YOUR_TELEGRAM_BOT_TOKEN") {
      return;
    }

    const sentKeys = getSentTelegramKeys();
    const itemsToSend = naItems.filter(item => !sentKeys.includes(item.trxKey));

    if (itemsToSend.length === 0) return;

    let message = `⚠️ *LAPORAN SN N/A (STATUS SUKSES)* ⚠️\n\n`;
    itemsToSend.forEach((item, index) => {
      message += `*#${index + 1} Komplain SN N/A*\n`;
      message += `Trx: ${item.produk}\n`;
      message += `Tujuan: ${item.tujuan}\n`;
      message += `Tgl: ${item.tglEntri}\n`;
      message += `Status: ${item.status}\n`;
      message += `SN: ${item.sn}\n`;
      message += `Supplier: ${item.supplier}\n\n`;
    });

    try {
      const res = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: TELEGRAM_CHAT_ID,
          text: message,
          parse_mode: 'Markdown'
        })
      });
      if (res.ok) {
        itemsToSend.forEach(item => markTelegramKeyAsSent(item.trxKey));
      }
    } catch (err) {
      console.error("Gagal mengirim notifikasi SN N/A ke Telegram:", err);
    }
  };

  // Kirim Telegram Notifikasi Laba Bermasalah (Negatif / NA / Kosong / Invalid) Anti-Duplikat
  const sendProblematicMarginAlert = async (problemItems) => {
    if (!TELEGRAM_BOT_TOKEN || !TELEGRAM_CHAT_ID || TELEGRAM_BOT_TOKEN === "YOUR_TELEGRAM_BOT_TOKEN") {
      return;
    }

    const sentKeys = getSentTelegramKeys();
    const itemsToSend = problemItems.filter(item => !sentKeys.includes(item.trxKey));

    if (itemsToSend.length === 0) return;

    let message = `🚨 *PERINGATAN: TRANSAKSI LABA BERMASALAH* 🚨\n\n`;
    itemsToSend.forEach((item, index) => {
      message += `*#${index + 1} Laba Bermasalah*\n`;
      message += `Tanggal & Waktu: ${item.tglEntri}\n`;
      message += `Nomor Tujuan: ${item.tujuan}\n`;
      message += `Produk: ${item.produk}\n`;
      message += `Harga Modal: ${formatRupiah(item.hargaBeli)}\n`;
      message += `Harga Jual: ${formatRupiah(item.hargaJual)}\n`;
      message += `Nilai Laba: ${formatRupiah(item.laba)}\n`;
      message += `Status Transaksi: ${item.status}\n`;
      message += `Supplier: ${item.supplier}\n`;
      message += `Keterangan: ${item.problemReason || 'Laba Bermasalah'}\n\n`;
    });

    try {
      const res = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: TELEGRAM_CHAT_ID,
          text: message,
          parse_mode: 'Markdown'
        })
      });
      if (res.ok) {
        itemsToSend.forEach(item => markTelegramKeyAsSent(item.trxKey));
      }
    } catch (err) {
      console.error("Gagal mengirim notifikasi Laba Bermasalah ke Telegram:", err);
    }
  };

  // Simpan Batch Baru ke Firestore Permanen
  const saveBatchToFirestore = async (items) => {
    try {
      const BATCH_SIZE = 400;
      for (let i = 0; i < items.length; i += BATCH_SIZE) {
        const chunk = items.slice(i, i + BATCH_SIZE);
        const batch = writeBatch(db);
        chunk.forEach(item => {
          const docRef = doc(collection(db, "speed_log_data"));
          const cleanItem = { ...item };
          delete cleanItem.trxKey;
          delete cleanItem.problemReason;
          batch.set(docRef, {
            ...cleanItem,
            rawDate: item.rawDate.toISOString()
          });
        });
        await batch.commit();
      }
    } catch (err) {
      console.error("Gagal menyimpan data permanen ke Firestore:", err);
    }
  };

  // Pemroses Data Utama Excel
  const processAndSetData = (dataRows) => {
    const mappedData = [];

    dataRows.forEach((item) => {
      try {
        let entriDate = item['A'] || item.tglEntri || item.Tanggal || item.tanggal || new Date(); 
        if (!(entriDate instanceof Date)) entriDate = new Date(entriDate);
        
        if (useCustomUploadDate && customUploadDate) {
          const [year, month, day] = customUploadDate.split('-');
          entriDate.setFullYear(parseInt(year), parseInt(month) - 1, parseInt(day));
        }

        const jawabanProvider = (item['N'] || item.jawabanProvider || item['Jawaban Provider'] || item.message || item.Message || "").toString();
        let finalTglStatus = "";

        const timeMatch = jawabanProvider.match(/(\d{2}[:\.]\d{2}[:\.]\d{2})/);

        if (timeMatch) {
          finalTglStatus = formatOtomaxDate(entriDate, timeMatch[0]);
        } else {
          const statusDate = new Date(entriDate.getTime() + 10000);
          finalTglStatus = formatOtomaxDate(statusDate);
        }

        // Pembacaan Status Presisi Mengacu pada Kolom S (JANGAN DARI KOLOM O / SN)
        const finalStatus = parseStatusFromRow(item);

        const produk = (item['C'] || item.produk || item['Produk'] || item['Kode Produk'] || item['Nama Produk'] || "").toString().toUpperCase();
        const tujuan = (item['E'] || item.tujuan || item['Tujuan'] || item['No Tujuan'] || "").toString();
        const sn = (item['O'] || item.sn || item['SN'] || "").toString();
        const hargaJual = item['L'] !== undefined ? item['L'] : (item.hargaJual !== undefined ? item.hargaJual : (item['Harga Jual'] || 0));
        const hargaBeli = item['K'] !== undefined ? item['K'] : (item.hargaBeli !== undefined ? item.hargaBeli : (item['Harga Modal'] || 0));
        const laba = item['M'] !== undefined ? item['M'] : (item.laba !== undefined ? item.laba : (item['Profit'] || 0));
        
        // Supplier Presisi
        const supplier = parseSupplierFromRow(item);
        const formattedTglEntri = formatOtomaxDate(entriDate);

        // Identitas Unik Transaksi (Anti-Duplikat Telegram)
        const trxKey = `${formattedTglEntri}_${produk}_${tujuan}_${sn}_${laba}`.replace(/\s+/g, '');

        // Cek Peringatan Laba Bermasalah
        const labaEval = evaluateLaba(laba);

        mappedData.push({
          rawDate: entriDate,
          tglEntri: formattedTglEntri,
          tglStatus: finalTglStatus,
          produk: produk,
          tujuan: tujuan,
          sn: sn,
          status: finalStatus,
          hargaJual: hargaJual,
          hargaBeli: hargaBeli,
          laba: laba,
          supplier: supplier,
          jawabanProvider: jawabanProvider,
          trxKey: trxKey,
          isProblematicLaba: labaEval.isProblem,
          problemReason: labaEval.reason
        });
      } catch (errRow) {
        console.error("Error membaca baris transaksi Excel:", errRow);
      }
    });

    if (mappedData.length === 0) return;

    // Transaksi Terbaru Paling Atas (Descending Sort)
    mappedData.sort((a, b) => b.rawDate - a.rawDate);

    // Simpan Ke Firestore Permanen
    saveBatchToFirestore(mappedData);

    // Cek Notifikasi Telegram SN N/A (Status Sukses)
    const naSuksesItems = mappedData.filter(item => {
      const isNA = item.sn.toUpperCase() === 'N/A' || item.sn.toUpperCase() === 'NA';
      const isSukses = item.status.toLowerCase() === 'sukses';
      return isNA && isSukses;
    });

    if (naSuksesItems.length > 0) {
      sendTelegramAlert(naSuksesItems);
    }

    // Cek Notifikasi Telegram Laba Bermasalah (Negatif / NA / Invalid)
    const problemLabaItems = mappedData.filter(item => item.isProblematicLaba);

    if (problemLabaItems.length > 0) {
      sendProblematicMarginAlert(problemLabaItems);
    }
  };

  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      setFileName(file.name);
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const dataArray = new Uint8Array(e.target.result);
          const workbook = XLSX.read(dataArray, { type: 'array', cellDates: true });
          const rawJson = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { 
            defval: "",
            header: "A" 
          });
          
          const firstCell = String(rawJson[0]?.['A'] || '').toLowerCase();
          const dataRows = (firstCell.includes('tgl') || firstCell.includes('entri') || firstCell.includes('tanggal')) ? rawJson.slice(1) : rawJson;
          processAndSetData(dataRows);
        } catch (err) { 
          console.error("Error processing excel:", err); 
        }
      };
      reader.readAsArrayBuffer(file);
    }
  };

  const filteredData = data.filter(item => {
    const s = searchTerm.toLowerCase();
    const matchesSearch = item.tujuan.toLowerCase().includes(s) || 
                          item.produk.toLowerCase().includes(s) || 
                          item.sn.toLowerCase().includes(s);
    const matchesStatus = statusFilter === 'ALL' || item.status.toLowerCase() === statusFilter.toLowerCase();
    let matchesDate = true;
    if (dateFilter) {
      const itemDateStr = item.rawDate.toISOString().split('T')[0];
      matchesDate = itemDateStr === dateFilter;
    }
    const isNA = item.sn.toUpperCase() === 'N/A' || item.sn.toUpperCase() === 'NA';
    const matchesNa = !filterNaOnly || isNA;

    return matchesSearch && matchesStatus && matchesDate && matchesNa;
  });

  const naRows = filteredData.filter(item => item.sn.toUpperCase() === 'N/A' || item.sn.toUpperCase() === 'NA');

  const copyToClipboard = () => {
    const text = naRows.map(item => 
      `Komplain SN N/A:\nTrx: ${item.produk}\nTujuan: ${item.tujuan}\nTgl: ${item.tglEntri}\nStatus: ${item.status}\nSN: ${item.sn}`
    ).join('\n\n');
    
    navigator.clipboard.writeText(text);
    alert('Format komplain berhasil disalin!');
  };

  const totalLaba = filteredData.reduce((acc, curr) => acc + (Number(curr.laba) || 0), 0);

  const HeaderCell = ({ title, colKey, hasArrow = false }) => (
    <th style={{ width: columnWidths[colKey] }} className="header-cell relative">
      <div className="flex items-center w-full h-full overflow-hidden">
        <div className="whitespace-nowrap flex-1 overflow-hidden text-clip leading-none text-black">
          {title}
        </div>
        {hasArrow && <ChevronDown size={10} className="text-gray-500 shrink-0 ml-[2px]" />}
      </div>
      <div 
        onMouseDown={(e) => handleResizeStart(e, colKey)} 
        onTouchStart={(e) => handleResizeStart(e, colKey)}
        className="resizer" 
      />
    </th>
  );

  return (
    <div className="w-full max-w-full overflow-hidden p-1 md:p-0">
      <div className="flex flex-col bg-[#D4D0C8] font-['Tahoma',sans-serif] text-[11px] text-black border border-[#808080] rounded-sm overflow-hidden h-[85vh] md:h-[600px] shadow-sm">
        
        {/* Header Summary Log */}
        <div className="bg-[#F0F0F0] border-b border-[#808080] px-2 py-1 flex items-center gap-4 text-[11px] font-bold select-none shrink-0">
          <div className="flex items-center gap-1">
            <span className="text-[#000080]">Total Transaksi:</span>
            <span>{filteredData.length}</span>
          </div>
          <div className="flex items-center gap-1">
            <span className="text-[#000080]">Total Laba:</span>
            <span className="text-green-700">{formatRupiah(totalLaba)}</span>
          </div>
        </div>

        {/* Toolbar & Filter */}
        <div className="bg-[#F0F0F0] border-b border-[#808080] p-[4px] flex flex-wrap items-center gap-1 shrink-0 select-none">
          <div className="flex items-center bg-white border border-[#7F9DB9] px-1 h-[24px] md:h-[20px] flex-1 min-w-[120px]">
            <Calendar size={11} className="text-gray-400 mr-1" />
            <input type="date" className="outline-none text-[10px] w-full bg-transparent" value={dateFilter} onChange={(e) => setDateFilter(e.target.value)} />
          </div>
          
          <div className="flex items-center bg-white border border-[#7F9DB9] px-1 h-[24px] md:h-[20px] flex-1 min-w-[120px]">
            <SearchIcon size={11} className="text-gray-400 mr-1" />
            <input type="text" className="outline-none w-full text-[11px]" placeholder="Cari..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>

          <div className="flex items-center gap-1 w-full md:w-auto">
            <select className="border border-[#7F9DB9] h-[24px] md:h-[20px] outline-none text-[11px] bg-white flex-1 md:w-20" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
              <option value="ALL">Semua</option>
              <option value="Sukses">Sukses</option>
              <option value="Gagal">Gagal</option>
            </select>

            {!fileName ? (
              <label className="flex items-center justify-center gap-1 px-2 h-[24px] md:h-[20px] bg-[#F0F0F0] border border-[#7F9DB9] hover:bg-[#E5E5E5] cursor-pointer text-[10px] flex-1 md:flex-none">
                <FileSpreadsheet size={11} className="text-green-700" />
                <span>Open</span>
                <input ref={fileInputRef} type="file" className="hidden" accept=".xlsx, .xls, .csv" onChange={handleFileUpload} />
              </label>
            ) : (
              <div className="flex items-center gap-1 bg-[#E1E1E1] border border-[#7F9DB9] px-2 h-[24px] md:h-[20px] text-[10px] flex-1 md:flex-none justify-between">
                <div className="flex items-center gap-1 overflow-hidden">
                  <FileSpreadsheet size={11} className="text-green-700" />
                  <span className="max-w-[60px] md:max-w-[80px] truncate uppercase text-black">{fileName}</span>
                </div>
                <button onClick={clearFile} className="ml-1 hover:text-red-600"><Trash2 size={11} /></button>
              </div>
            )}
          </div>

          {/* Fitur Edit Tanggal Upload */}
          <div className="flex items-center gap-1 border border-[#A0A0A0] bg-[#E1E1E1] p-[2px] h-[24px] md:h-[20px] rounded-sm">
            <label className="flex items-center gap-1 cursor-pointer text-[10px] font-semibold text-gray-700 px-1">
              <input 
                type="checkbox" 
                checked={useCustomUploadDate} 
                onChange={(e) => setUseCustomUploadDate(e.target.checked)}
                className="w-3 h-3"
              />
              <span>Ubah Tgl</span>
            </label>
            {useCustomUploadDate && (
              <input 
                type="date" 
                className="outline-none text-[10px] bg-white border border-[#7F9DB9] px-1 h-full font-sans" 
                value={customUploadDate} 
                onChange={(e) => setCustomUploadDate(e.target.value)} 
              />
            )}
          </div>

          {/* Filter Cek SN */}
          <button
            onClick={() => setFilterNaOnly(prev => !prev)}
            className={`flex items-center gap-1 px-2 h-[24px] md:h-[20px] text-[10px] font-semibold border border-[#7F9DB9] rounded-sm transition-colors ${
              filterNaOnly ? 'bg-orange-600 text-white' : 'bg-[#E1E1E1] text-black hover:bg-[#D5D5D5]'
            }`}
          >
            <AlertTriangle size={11} className={filterNaOnly ? 'text-white' : 'text-orange-600'} />
            <span>Cek SN</span>
          </button>
        </div>

        {/* Tabel Data Log Transaksi */}
        <div className="flex-1 bg-white overflow-auto scrollbar-otomax touch-auto selection:bg-[#316AC5] selection:text-white">
          <div className="bg-white inline-block min-w-full">
            <table className="border-collapse table-fixed w-full" style={{ tableLayout: 'fixed' }}>
              <thead className="sticky top-0 z-20 select-none">
                <tr className="bg-[#F2F2F2]">
                  <th className="header-cell" style={{ width: '30px', textAlign: 'center' }}>#</th>
                  <HeaderCell title="Tgl. Entri" colKey="tglEntri" hasArrow={true} />
                  <HeaderCell title="Tgl. Status" colKey="tglStatus" />
                  <HeaderCell title="Produk" colKey="produk" />
                  <HeaderCell title="Tujuan" colKey="tujuan" />
                  <HeaderCell title="SN" colKey="sn" />
                  <HeaderCell title="Status" colKey="status" />
                  <HeaderCell title="Harga Jual" colKey="hargaJual" />
                  <HeaderCell title="Harga Beli" colKey="hargaBeli" />
                  <HeaderCell title="Laba" colKey="laba" />
                  <HeaderCell title="Supplier" colKey="supplier" />
                  <HeaderCell title="Jawaban Provider" colKey="jawabanProvider" />
                </tr>
              </thead>
              <tbody>
                {filteredData.map((item, idx) => {
                  const isGagal = item.status.toLowerCase() === 'gagal';
                  const isNA = item.sn.toUpperCase() === 'N/A' || item.sn.toUpperCase() === 'NA';
                  
                  let rowBgClass = idx % 2 === 1 ? 'bg-[#F5F5F5]' : 'bg-white';
                  
                  if (isGagal) {
                    rowBgClass = 'bg-[#FF4D4D] text-white'; 
                  } else if (isNA) {
                    rowBgClass = 'bg-[#FFF4CE]';
                  }
                  
                  return (
                    <tr key={item.id || idx} className={`row-otomax ${rowBgClass}`}>
                      <td className={`cell-otomax text-center select-none border-r-[#808080] text-[9px] ${isGagal ? 'bg-[#E60000] text-white' : 'bg-[#F0F0F0] text-gray-600'}`} style={{ width: '30px' }}>{idx + 1}</td>
                      <td className="cell-otomax" style={{ width: columnWidths.tglEntri }}>{item.tglEntri}</td>
                      <td className="cell-otomax" style={{ width: columnWidths.tglStatus }}>{item.tglStatus}</td>
                      <td className="cell-otomax" style={{ width: columnWidths.produk }}>{item.produk}</td>
                      <td className="cell-otomax" style={{ width: columnWidths.tujuan }}>{item.tujuan}</td>
                      <td className={`cell-otomax ${isNA && !isGagal ? 'font-bold text-orange-700' : ''}`} style={{ width: columnWidths.sn }}>{item.sn}</td>
                      <td className="cell-otomax" style={{ width: columnWidths.status }}>{item.status}</td>
                      <td className="cell-otomax text-right" style={{ width: columnWidths.hargaJual }}>{formatRupiah(item.hargaJual)}</td>
                      <td className="cell-otomax text-right" style={{ width: columnWidths.hargaBeli }}>{formatRupiah(item.hargaBeli)}</td>
                      <td className="cell-otomax text-right" style={{ width: columnWidths.laba }}>{formatRupiah(item.laba)}</td>
                      <td className="cell-otomax" style={{ width: columnWidths.supplier }}>{item.supplier}</td>
                      <td className="cell-otomax" style={{ width: columnWidths.jawabanProvider }}>{item.jawabanProvider}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {/* Banner Notifikasi Komplain SN N/A */}
        {naRows.length > 0 && (
          <div className="bg-[#FFF4CE] border-y border-[#808080] p-1 flex items-center justify-between animate-pulse select-none">
            <div className="flex items-center gap-2 text-[#856404] font-bold text-[10px]">
              <AlertTriangle size={14} className="text-orange-600" />
              <span>DITEMUKAN {naRows.length} DATA DENGAN SN: N/A</span>
            </div>
            <button 
              onClick={copyToClipboard}
              className="win-btn flex items-center gap-1 px-2 py-0.5 bg-[#E1E1E1]"
            >
              <Copy size={10} />
              SALIN KOMPLAIN
            </button>
          </div>
        )}

        {/* Status Bar Bawah */}
        <div className="bg-[#D4D0C8] border-t border-[#808080] text-black px-1 h-[24px] md:h-[22px] flex items-center justify-between shrink-0 text-[10px] select-none">
          <div className="flex items-center gap-2">
              <label className="flex items-center gap-1 cursor-pointer hover:bg-white/50 px-1 py-0.5 border border-transparent active:border-[#808080]">
                <input 
                  type="checkbox" 
                  checked={isAutoFit} 
                  onChange={(e) => setIsAutoFit(e.target.checked)}
                  className="w-3 h-3"
                />
                <span className="leading-none">Resize</span>
              </label>
              <div className="w-[1px] h-3 bg-[#808080] mx-1" />
              <span className="opacity-70">Otomax Speed Log</span>
          </div>
          
          <div className="flex items-center gap-1">
             <button onClick={handleReset} className="win-btn px-2">Reset Filter</button>
             <button 
               onClick={handleResetDatabase} 
               className="win-btn px-2 text-red-[#700] font-bold flex items-center gap-1 hover:bg-red-100"
               title="Hapus seluruh database permanen di Firebase"
             >
               <RotateCcw size={10} />
               Reset Database
             </button>
          </div>
        </div>

        <style>{`
          .scrollbar-otomax::-webkit-scrollbar { width: 14px; height: 14px; }
          .scrollbar-otomax::-webkit-scrollbar-track { background: #F0F0F0; border-left: 1px solid #C0C0C0; }
          .scrollbar-otomax::-webkit-scrollbar-thumb { 
            background: #D4D0C8; border: 1px solid #FFFFFF; 
            box-shadow: inset -1px -1px #808080, inset 1px 1px #FFF; 
          }
          .win-btn { 
            background: #D4D0C8; color: black; font-weight: normal; 
            height: 16px; border: 1px solid #FFF;
            box-shadow: inset 1px 1px #fff, 1px 1px #404040; line-height: 1; 
            font-size: 9px;
            cursor: pointer;
          }
          .win-btn:active {
            box-shadow: inset -1px -1px #fff, inset 1px 1px #404040;
          }
          .header-cell {
            border: 1px solid #A0A0A0; padding: 0 3px; height: 22px;
            background: #F2F2F2; font-weight: normal; text-align: left;
            font-family: 'Tahoma', sans-serif;
            overflow: hidden;
          }
          .resizer {
            position: absolute; right: 0; top: 0; bottom: 0; width: 8px;
            cursor: col-resize; z-index: 10;
          }
          .row-otomax { height: 18px; transition: none; display: table-row; }
          
          .cell-otomax {
              border: 1px solid #D0D0D0;
              padding: 0 3px;
              height: 18px;
              font-family: 'Tahoma', sans-serif;
              color: inherit;
              white-space: nowrap;
              overflow: hidden;
              text-overflow: clip;
              display: table-cell;
              vertical-align: middle;
              user-select: text;
          }

          @media (hover: hover) {
            .row-otomax:hover { 
              background-color: #E8F2FF !important;
              color: black !important;
            }
          }
          
          @media (max-width: 640px) {
            .win-btn { height: 18px; padding: 0 6px; }
          }
        `}</style>
      </div>
    </div>
  );
};

export default LogSpeedPanel;